package com.yeyamo_mobile.api.discovery_service.application;import com.yeyamo_mobile.api.discovery_service.domain.model.DiscoveryType;
public record DiscoverySearch(String query,DiscoveryType type,String categoryCode,String regionCode,Double latitude,Double longitude,Double radiusKm,int page,int size,boolean trends){public DiscoverySearch{page=Math.max(0,page);size=Math.max(1,Math.min(50,size));if((latitude==null)!=(longitude==null))throw new IllegalArgumentException("lat and lng are required together");if(latitude!=null&&(latitude < -90||latitude > 90||longitude < -180||longitude > 180))throw new IllegalArgumentException("Invalid coordinates");if(radiusKm!=null&&(radiusKm<=0||radiusKm>200))throw new IllegalArgumentException("radiusKm must be between 0 and 200");}}
